"""Focused primary-source evidence ledger, reviewed before experiments."""
from pathlib import Path
import json,pandas as pd
ROOT=Path(__file__).resolve().parents[2]
FIELDS=['citation','year','evidence_status','dataset','task','architecture','input_resolution','preprocessing','training_strategy','loss','metrics','reported_results','external_validation','strengths','limitations','relevance','source_url']

def run():
    rows=[]
    def add(c,y,status,data,task,arch,res,prep,train,loss,metrics,result,external,strength,limit,relevance,url):rows.append(dict(zip(FIELDS,[c,y,status,data,task,arch,res,prep,train,loss,metrics,result,external,strength,limit,relevance,url])))
    nr='Not extracted from the reviewed source; do not infer'
    add('Goh et al., Comparative Analysis of Vision Transformers and Conventional CNNs in Detecting Referable DR, Ophthalmology Science, doi:10.1016/j.xops.2024.100552',2024,'Peer-reviewed; abstract and accessible primary excerpts','41,614 Kaggle photographs; two external test sets','Binary referable DR','Five CNNs and four ViTs, including ResNet50 and Swin-T',nr,nr,nr,nr,'Sensitivity at fixed specificity','Swin sensitivity 94.4% at 80% specificity internally; CNN range 76.3–83.8%','Reported two external sets; detailed independence audit not verified','Contemporary head-to-head with external evaluation','Binary endpoint, much larger data; patient split/augmentation timing not verified here','Motivates testing both families, not declaring Swin our five-grade winner','https://pmc.ncbi.nlm.nih.gov/articles/PMC11334703/')
    add('Ding et al., HRDecoder: High-Resolution Decoder Network for Fundus Image Lesion Segmentation',2024,'arXiv preprint; full methods/table reviewed','IDRiD 54/27; DDR 383/149/225','Four-lesion segmentation','HRNetv2 plus high-resolution decoder; ConvNeXt variant','IDRiD 2880×1920; train crops 1920²','Resize and crop; sliding-window inference','SGD 0.01; batch 4; 20k/40k iterations; three repeats',nr,'AUPR, F, IoU','IDRiD mean AUPR 71.29%, F 67.41%, IoU 51.94%; MA F 49.35%','Separate dataset experiments are not necessarily cross-domain transfer','Explicit global/detail and compute analysis','Large compute; official split caveats differ from our protocol','Supports native-detail experiment; not a performance target','https://arxiv.org/html/2411.03976v1')
    add('Dutta and Jeong, Multi-Resolution Feature Stem for DR lesion segmentation',2026,'arXiv preprint, not verified peer-reviewed; full methods reviewed','DDR; 383 training photographs','Four-lesion segmentation','U-Net, U-Net++, DeepLabV3+, FPN; proposed multiresolution U-Net++','512² versus 1024²','Aspect-preserved resize and center crop; bilinear image/nearest mask','M4 Max and A100; geometric/photometric augmentation','0.6 focal + 0.4 Dice','mAP, mIoU, lesion AP/IoU','Proposed test mAP .3985; mIoU .2853; HE below its best baseline','No locked independent-source transfer established','Lesion-specific trade-offs instead of assuming higher is always better','Resolution/crop, protocol and preliminary weight tuning confound comparisons','Measure MA and each other lesion separately; avoid universal claims','https://arxiv.org/html/2607.08679v1')
    add('Fang, Ma, Qian, Multi-task transformer framework and radiomic signatures, Photodiagnosis Photodyn Ther, doi:10.1016/j.pdpdt.2026.105455',2026,'Peer-reviewed PubMed abstract; full methods not independently inspected','987 lesion images; 6,852 four-class grading images, two clinical centers','Segmentation, detection and four-class grading','UNet++, CE-Net, Swin-UNet, SegFormer; ViT versus radiomics classifiers',nr,'CLAHE, artifact filtering, retinal masking','Harmonized settings; internal CV and external multicenter testing',nr,'Dice, mAP, accuracy, AUC','Reported external radiomics accuracy .883/AUC .947 versus ViT .838/.902; lesion Dice .871–.963','Reported multicenter; exact protocol needs full-text audit','Already combines lesion analysis and grading evidence','Four-class outcome; unknown patient grouping/pretraining details in abstract','Combining grading and segmentation is not novelty; no basis for automatic fusion','https://pubmed.ncbi.nlm.nih.gov/41895558/')
    add('Jiang et al., GlanceSeg, IEEE JBHI, doi:10.1109/JBHI.2024.3377592',2025,'Peer-reviewed PubMed; DOI 2024, issue December 2025','IDRiD and Retinal-Lesions with gaze-related annotations','MA segmentation and annotation assistance','Gaze-prompted SAM plus domain filtering',nr,'Gaze ROI and saliency prompts','Human-in-loop; optional annotation fine-tuning',nr,'Quantitative metrics not extracted','No numeric claim extracted from abstract','Two dataset evaluations; independent autonomous deployment not established','Targets minute lesions and annotation efficiency','Requires gaze/prompt information absent from our masks-only protocol','Do not compare prompted/human-assisted results to our automatic baseline','https://pubmed.ncbi.nlm.nih.gov/38483801/')
    foundational=[
    ('He et al., Deep Residual Learning for Image Recognition (CVPR 2016)',2016,'ImageNet; CIFAR; COCO','Image recognition','ResNet','Residual paths provide a standard transfer baseline','https://arxiv.org/abs/1512.03385'),
    ('Huang et al., Densely Connected Convolutional Networks (CVPR 2017)',2017,'CIFAR, SVHN, ImageNet','Image recognition','DenseNet','Feature reuse; retain as literature alternative, no extra tournament slot','https://arxiv.org/abs/1608.06993'),
    ('Tan and Le, EfficientNet (ICML 2019)',2019,'ImageNet','Image recognition','EfficientNet','Compound scaling; B0 is the compact comparator, B7 results do not describe B0','https://arxiv.org/abs/1905.11946'),
    ('Liu et al., A ConvNet for the 2020s (CVPR 2022)',2022,'ImageNet, COCO, ADE20K','Classification/dense prediction','ConvNeXt','Modern CNN controls against attributing all gains to attention','https://arxiv.org/abs/2201.03545'),
    ('Liu et al., Swin Transformer (ICCV 2021)',2021,'ImageNet, COCO, ADE20K','Classification/dense prediction','Swin','Hierarchical local attention; resolution scalable compared with global ViT','https://arxiv.org/abs/2103.14030'),
    ('Dosovitskiy et al., An Image is Worth 16x16 Words (ICLR 2021)',2021,'Large-scale pretraining; ImageNet, CIFAR, VTAB','Image recognition','ViT','Data/pretraining dependence cautions against scratch training on 404 images','https://arxiv.org/abs/2010.11929'),
    ('Ronneberger et al., U-Net (MICCAI 2015)',2015,'Microscopy segmentation','Biomedical segmentation','U-Net','Skip connections preserve localization; baseline decoder','https://arxiv.org/abs/1505.04597'),
    ('Zhou et al., UNet++ (DLMIA/ML-CDS 2018)',2018,'CT, microscopy, colonoscopy','Medical segmentation','U-Net++','Nested skip paths are a controlled increase in decoder complexity','https://arxiv.org/abs/1807.10165'),
    ('Chen et al., Encoder-Decoder with Atrous Separable Convolution (ECCV 2018)',2018,'PASCAL VOC, Cityscapes','Semantic segmentation','DeepLabV3+','Atrous context with decoder; small-lesion output stride must be considered','https://arxiv.org/abs/1802.02611'),
    ('Lin et al., Feature Pyramid Networks (CVPR 2017)',2017,'COCO','Object detection','FPN','Lateral multiscale features; not originally a retinal segmentation system','https://arxiv.org/abs/1612.03144'),
    ('Xie et al., SegFormer (NeurIPS 2021)',2021,'ADE20K, Cityscapes','Semantic segmentation','MiT encoder and MLP decoder','Lightweight B0 attention comparator; no absolute positional encoding','https://arxiv.org/abs/2105.15203'),
    ('Cao et al., Swin-Unet (2021 preprint; ECCV workshops 2022)',2022,'Medical segmentation benchmarks','Medical segmentation','Swin-Unet','Pure transformer alternative; not an additional local grid dimension','https://arxiv.org/abs/2105.05537')]
    for cite,year,data,task,arch,rel,url in foundational:add(cite,year,'Foundational author source; abstract-level extraction',data,task,arch,nr,nr,'Paper-specific; local implementation/weights documented separately',nr,'Paper benchmark metrics; no local DR result','No architecture-specific number transposed to our task','Not evidence of retinal external validation','Established architecture mechanism','Domain and training recipes differ; full hyperparameter extraction incomplete',rel,url)
    add('Hou, Yu, Samaras, Squared Earth Mover’s Distance loss for ordered classes',2016,'Author preprint / NIPS 2017 workshop version','Age and image aesthetics','Ordinal classification','CNN with cumulative-distribution loss',nr,nr,'Supervised ordered targets','Squared differences of cumulative class distributions','Ordered prediction performance','No numerical result imported','Not retinal external validation','Simple objective keeps a standard five-probability interface','Equal grade spacing is an analysis convention, not calibrated clinical harm','Test CE plus fixed-strength cumulative penalty, not a novel ordinal network','https://arxiv.org/abs/1611.05916')
    add('Lin et al., Focal Loss for Dense Object Detection (ICCV 2017)',2017,'Peer-reviewed foundational source','COCO','Dense detection','RetinaNet',nr,nr,'Downweight easy examples','Focal loss','Detection AP','No DR performance inferred','Not retinal external validation','Direct foreground/background imbalance rationale','Detection success does not guarantee five-class grading benefit','Compare fixed gamma=2 against CE/weighted CE on training-only folds','https://arxiv.org/abs/1708.02002')
    add('Guo et al., On Calibration of Modern Neural Networks (ICML 2017)',2017,'Peer-reviewed PMLR','Image and document classification','Probability calibration','Post-hoc temperature scaling',nr,nr,'Fit scalar temperature on held-out calibration data','Negative log likelihood','Reliability/calibration measures','Temperature scaling often effective; no DR number imported','No retinal validation','Separates confidence from correctness','Fitting temperature and reporting calibration on the same predictions is optimistic','Report raw Brier/NLL/ECE; any later fitted calibration needs independent/cross-fitted evaluation','https://proceedings.mlr.press/v70/guo17a.html')
    add('Salehi, Erdogmus, Gholipour, Tversky loss function for image segmentation',2017,'Author source; adaptive MA follow-up reference','Multiple-sclerosis MRI lesions','Imbalanced lesion segmentation','3D fully convolutional networks',nr,nr,'Supervised lesion segmentation','Asymmetric Tversky index','Dice, F2, precision-recall area','Improved trade-off reported; no numeric retinal result imported','Not retinal external validation','Explicit FP/FN trade-off for sparse positives','MRI result does not validate MA loss coefficients or clinical costs','Justifies a bounded MA-only hypothesis; coefficients are engineering choices','https://arxiv.org/abs/1706.05721')
    out=ROOT/'outputs/metrics/model_selection';out.mkdir(parents=True,exist_ok=True)
    pd.DataFrame(rows).to_csv(out/'literature_evidence.csv',index=False)
    text='''# DR model literature review

Search/review date: 2026-10-28. Focused primary-source review, not a systematic review or meta-analysis. Queries covered 2024–2026 DR CNN/transformer comparisons, MA/local-global segmentation, ordinal losses and external validation. Author arXiv texts are labeled preprints; PubMed indexing is not independent validation. Some PMC/full-text requests returned CAPTCHA or inaccessible PDF responses; inaccessible details remain explicitly unextracted. Numeric literature results below are **reported**, never our results. The initial 20-source review preceded initial fitting. Tversky was added after observing baseline MA failures and before the explicitly adaptive MA follow-up; it was not an initial preregistered choice.

The strongest reasons for our design are task compatibility and our audited data: 404 content-clean development images, only 18 grade-1 training labels, unknown patient grouping, and 35.459% MA component loss at width 224. Binary referable-DR, four-class DR, five-class DR and pixel segmentation results are not interchangeable. High accuracy on selected/imbalanced data is not architecture evidence by itself.

For each study, critically audit sample independence, whether augmentation followed splitting, label compatibility, patient grouping, external cohorts, pretraining overlap and model/threshold selection. “Not extracted” below is a review limitation, not proof that authors failed to report a detail. Our local duplicate findings prohibit assuming published official IDRiD splits are leakage-free. Separate training on IDRiD and DDR is not automatically cross-domain validation. Test-led selection on an alleged external cohort would also weaken its independence.

## Evidence ledger

Every requested extraction field is recorded in `outputs/metrics/model_selection/literature_evidence.csv`. The concise records below avoid presenting missing methods as known.
'''
    for r in rows:
        text+=f"\n### {r['citation']}\n\n[{r['evidence_status']}]({r['source_url']})\n\n"+'\n\n'.join(f"**{k.replace('_',' ').capitalize()}:** {r[k]}" for k in FIELDS if k not in ['citation','evidence_status','source_url'])+'\n'
    text+='''
## Translation into prespecified local experiments

- ResNet50 establishes difficulty; EfficientNet-B0 tests compactness; ConvNeXt-Tiny distinguishes a modern convolutional recipe from Swin-Tiny attention. DenseNet121, EfficientNet-B2 and global ViT are literature alternatives, not extra grid slots.
- Frozen ImageNet features test what transfers without representation adaptation; controlled last-stage fine-tuning tests whether adaptation helps with 404 labels. Different published pretrained recipes remain a confound even when all use ImageNet-1k.
- Use common aspect-preserving resize plus padding, ImageNet channel normalization, AdamW family and checkpoint rule. Do not copy aggressive medical image enhancements without ablation. Cropping may remove border artifacts but also changes field of view.
- Three stratified folds give six grade-1 validation cases per fold; fixed seeds separate optimization variability from split variability. These remain image-level, not patient-level folds. Model-selection CV is optimistically selected and is not final generalization evidence.
- Grading loss candidates are CE, training-fold-only inverse-frequency weighted CE, fixed gamma-2 focal loss and CE plus a fixed cumulative squared-distance penalty. No validation labels enter class weights or sample generation.
- Segmentation starts with U-Net/U-Net++/DeepLabV3+ sharing a pretrained residual encoder; SegFormer-B0 changes encoder family and is therefore a model-package comparison, not a decoder-only causal experiment. Mask availability gates loss and metrics.
- A native 256/512 patch retains source pixel sampling but loses global context. Full-image and patch predictions must be evaluated on the same original validation images, not separately selected lesion patches. Split image identities before extracting patches. Record tiling cost and component matching.
- Grad-CAM/attention compatibility is not proof of explanation faithfulness. No joint lesion/grading system or novelty claim is justified without observed complementary baseline errors and resolved correspondence. External validation, gradability and clinical utility remain unestablished.
'''
    (ROOT/'docs/research/DR_MODEL_LITERATURE_REVIEW.md').write_text(text,encoding='utf-8')
    (out/'literature_review_completed.json').write_text(json.dumps({'review_date':'2026-10-28','primary_source_records':len(rows),'initial_review_records':20,'initial_review_before_initial_fits':True,'adaptive_reference':'Tversky added before MA-only follow-up, after baseline failures','full_text_access_limits':['PMC CAPTCHA','some PDF inaccessible'],'external_validation_performed_locally':False},indent=2))
    print('Literature evidence records:',len(rows))

if __name__=='__main__':run()
